{
  "name": "genesis-release-integrity",
  "version": "1.0.0",
  "description": "Publish an explicit, inspectable package of known bytes.",
  "main": "index.cjs",
  "engines": {
    "node": ">=20"
  },
  "scripts": {
    "test": "node --test --test-reporter=tap test/index.test.cjs",
    "demo": "node examples/demo.cjs"
  },
  "license": "MIT",
  "author": "Genesis Contributors",
  "repository": {
    "type": "git",
    "url": "https://github.com/Wassimyounes01/genesis-release-integrity.git"
  }
}

'use strict';
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),os=require('node:os'),path=require('node:path');
const {inspectRelease,verifyRelease}=require('../index.cjs');
function fixture(t){const root=fs.mkdtempSync(path.join(os.tmpdir(),'release-test-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));fs.writeFileSync(path.join(root,'README.md'),'Portable system by contributors@example.invalid');return {root,files:['README.md']};}
test('manifest round trip verifies identical consumer files',t=>{const f=fixture(t),r=inspectRelease(f);assert.equal(r.ok,true);assert.equal(verifyRelease({...f,manifest:r.manifest}).ok,true);});
test('consumer tampering fails',t=>{const f=fixture(t),r=inspectRelease(f);fs.writeFileSync(path.join(f.root,'README.md'),'changed');assert.equal(verifyRelease({...f,manifest:r.manifest}).ok,false);});
test('extra file in explicit consumer inventory fails',t=>{const f=fixture(t),r=inspectRelease(f);fs.writeFileSync(path.join(f.root,'extra.txt'),'extra');assert.equal(verifyRelease({...f,files:[...f.files,'extra.txt'],manifest:r.manifest}).ok,false);});
test('credentials blocked without echoing their value',t=>{const f=fixture(t);const token='ghp_'+'a'.repeat(32);fs.writeFileSync(path.join(f.root,'README.md'),token);const r=inspectRelease(f);assert.equal(r.ok,false);assert.equal(JSON.stringify(r).includes(token),false);});
test('private terms and real email shapes blocked',t=>{const f=fixture(t);fs.writeFileSync(path.join(f.root,'README.md'),'InternalBrand user@'+'company.invalid');assert.equal(inspectRelease({...f,forbiddenTerms:['InternalBrand']}).findings.length,2);});
test('traversal, private paths and duplicate paths refused',t=>{const f=fixture(t);for(const files of [['../x'],['.env'],['memory/log.txt'],['README.md','README.md']])assert.throws(()=>inspectRelease({...f,files}));});
test('binary and excessive files fail closed',t=>{const f=fixture(t);fs.writeFileSync(path.join(f.root,'README.md'),Buffer.from([0,255]));assert.equal(inspectRelease(f).ok,false);fs.writeFileSync(path.join(f.root,'README.md'),Buffer.alloc(1024*1024+1));assert.throws(()=>inspectRelease(f));});
test('private names cannot leak through the manifest',t=>{const f=fixture(t);for(const name of ['team@'+'company.invalid.txt','PrivateBrand.md','ghp_'+'a'.repeat(32)+'.txt']){fs.writeFileSync(path.join(f.root,name),'public');assert.throws(()=>inspectRelease({...f,files:[name],forbiddenTerms:['PrivateBrand']}));}});
test('project keys and escaped or macOS home paths are blocked',t=>{const f=fixture(t);for(const value of ['sk-proj-'+'a'.repeat(32),'/Us'+'ers/fixture/file',JSON.stringify('C:'+String.fromCharCode(92)+'Users'+String.fromCharCode(92)+'fixture')]){fs.writeFileSync(path.join(f.root,'README.md'),value);assert.equal(inspectRelease(f).ok,false);}});
